CREATE OR REPLACE FUNCTION public.hr_approval_actor_name(_id uuid,_kind text) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid; cid uuid; recipient uuid; BEGIN IF NOT public.is_psa_staff() THEN RAISE EXCEPTION 'not_approver'; END IF; IF _kind='remote' THEN SELECT aprovado_por,collaborator_id INTO actor,cid FROM public.remote_work_requests WHERE id=_id; IF cid IS NULL OR NOT public.remote_work_can_approve(auth.uid(),cid) THEN RAISE EXCEPTION 'not_approver'; END IF; ELSIF _kind='change' THEN SELECT decided_by,recipient_id INTO actor,recipient FROM public.vacation_change_requests WHERE id=_id; IF recipient IS DISTINCT FROM auth.uid() AND NOT public.can_approve_leave(auth.uid()) THEN RAISE EXCEPTION 'not_recipient'; END IF; ELSIF _kind='leave' THEN IF NOT public.can_approve_leave(auth.uid()) THEN RAISE EXCEPTION 'not_approver'; END IF; SELECT aprovado_por INTO actor FROM public.vacation_requests WHERE id=_id; ELSE RAISE EXCEPTION 'invalid_kind'; END IF; RETURN (SELECT coalesce(c.nome,u.raw_user_meta_data->>'full_name',u.email)::text FROM auth.users u LEFT JOIN public.collaborators c ON lower(c.email)=lower(u.email) WHERE u.id=actor LIMIT 1); END $$;
REVOKE ALL ON FUNCTION public.hr_approval_actor_name(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.hr_approval_actor_name(uuid,text) TO authenticated;